import { Component, computed, input } from '@angular/core';
import { HrmAvatar, HrmTag } from 'hrm-ui';
import { Employee, STATUS_META } from './_data';

/** Nội dung chi tiết 1 nhân viên — dùng chung cho detail-peek (drawer/modal) và trang full-page.
 *  Demo: prose tiếng Việt (playground i18n-exempt). */
@Component({
  selector: 'sg-employee-detail',
  imports: [HrmAvatar, HrmTag],
  template: `
    @if (emp(); as e) {
      <div class="ed" [class.ed--full]="full()">
        <div class="ed-hero">
          <hrm-avatar [text]="initials(e.name)" [colorSeed]="e.name" [colorful]="true" size="large" />
          <div class="ed-hero-info">
            <div class="ed-name">{{ e.name }}</div>
            <div class="ed-role">{{ e.role }} · {{ e.dept }}</div>
          </div>
          <hrm-tag [color]="tone(e)" variant="light" [dot]="true">{{ statusLabel(e) }}</hrm-tag>
        </div>

        <div class="ed-kpi">
          <div class="ed-kpi-top"><span>Hiệu suất KPI</span><span class="ed-kpi-v">{{ e.kpi }}%</span></div>
          <div class="ed-bar"><span class="ed-bar-fill" [style.width.%]="e.kpi" [style.background]="kpiColor(e.kpi)"></span></div>
        </div>

        <div class="ed-fields">
          @for (f of fields(e); track f.label) {
            <div class="ed-field">
              <div class="ed-flabel">{{ f.label }}</div>
              <div class="ed-fvalue">{{ f.value }}</div>
            </div>
          }
        </div>

        <div class="ed-block">
          <div class="ed-blabel">Kỹ năng</div>
          <div class="ed-skills">
            @for (s of e.skills; track s) { <hrm-tag color="blue" variant="light" size="sm">{{ s }}</hrm-tag> }
          </div>
        </div>
      </div>
    }
  `,
  styles: [`
    :host { display: block; }
    .ed { display: flex; flex-direction: column; gap: 20px; }
    .ed-hero { display: flex; align-items: center; gap: 14px; }
    .ed-hero-info { flex: 1; min-width: 0; }
    .ed-name { font-size: var(--fs-18); font-weight: 700; color: var(--text-strong); }
    .ed-role { font-size: var(--fs-13); color: var(--text-sub); margin-top: 2px; }
    .ed-kpi-top { display: flex; justify-content: space-between; font-size: var(--fs-13); color: var(--text-sub); margin-bottom: 6px; }
    .ed-kpi-v { font-weight: 700; color: var(--text-strong); }
    .ed-bar { height: 8px; border-radius: var(--radius-full); background: var(--skeleton); overflow: hidden; }
    .ed-bar-fill { display: block; height: 100%; border-radius: var(--radius-full); }
    .ed-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 20px; }
    .ed--full .ed-fields { grid-template-columns: repeat(3, 1fr); }
    .ed-flabel { font-size: var(--fs-12); color: var(--text-soft); margin-bottom: 2px; }
    .ed-fvalue { font-size: var(--fs-14); color: var(--text-body); }
    .ed-blabel { font-size: var(--fs-12); color: var(--text-soft); margin-bottom: 8px; }
    .ed-skills { display: flex; flex-wrap: wrap; gap: 6px; }
  `],
})
export class SgEmployeeDetail {
  readonly emp = input<Employee | null>(null);
  /** Trình bày rộng hơn (3 cột) cho trang full-page. */
  readonly full = input(false);

  protected initials(name: string): string {
    const p = name.trim().split(/\s+/);
    return ((p[0]?.[0] ?? '') + (p.length > 1 ? p[p.length - 1][0] : '')).toUpperCase();
  }
  protected tone(e: Employee): 'green' | 'yellow' | 'gray' {
    return e.status === 'active' ? 'green' : e.status === 'leave' ? 'yellow' : 'gray';
  }
  protected statusLabel(e: Employee): string { return STATUS_META[e.status].label; }
  protected kpiColor(v: number): string {
    return v >= 80 ? 'var(--success-base)' : v >= 60 ? 'var(--warning-base)' : 'var(--error-base)';
  }
  protected fields(e: Employee): { label: string; value: string }[] {
    return [
      { label: 'Email', value: e.email },
      { label: 'Điện thoại', value: e.phone },
      { label: 'Phòng ban', value: e.dept },
      { label: 'Quản lý', value: e.manager },
      { label: 'Nơi làm việc', value: e.location },
      { label: 'Ngày vào', value: e.joined },
    ];
  }
}
